<html>
<head>
  <meta charset="UTF-8">
  <title>User Feedback</title>
</head>
<body>
  <h2>User Feedback Received</h2>
  <p><strong>Submitted by:</strong> %s</p>
  <p><strong>Subject:</strong> %s</p>
  <div><strong>Message:</strong><br>
    <pre style="font-family: Arial, sans-serif; background-color: #f9f9f9; padding: 10px; border: 1px solid #ddd;">%s</pre>
  </div>
</body>
</html>`,
		escapedUserName,
		escapedSubject,
		escapedFeedbackContent,
	)

	// Combine headers and body to form complete email message
	// This format is ready to be used with net/smtp.SendMail
	emailMessage := headers + htmlBody

	return emailMessage, nil
}

func main() {
	// Example usage
	emailBody, err := BuildFeedbackEmail(
		"noreply@example.com",
		"support@example.com",
		"John Doe",
		"Bug Report",
		"I found a bug in the application when clicking the submit button.",
	)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Println(emailBody)
}

