// sanitizeHeaderValue removes characters that could be used for header injection
func sanitizeHeaderValue(value string) string {
	// Remove any CR, LF, or null characters that could be used for header injection
	value = strings.ReplaceAll(value, "\r", "")
	value = strings.ReplaceAll(value, "\n", "")
	value = strings.ReplaceAll(value, "\x00", "")
	return value
}

// BuildFeedbackEmail constructs a complete RFC 5322-compliant email message
