// sanitizeHeaderValue removes or replaces characters that could be used
// for email header injection attacks (CR, LF, and null bytes)
func sanitizeHeaderValue(value string) string {
	// Remove carriage return, line feed, and null bytes
	// These characters can be used to inject additional headers
	result := strings.ReplaceAll(value, "\r", "")
	result = strings.ReplaceAll(result, "\n", "")
