// BuildFeedbackEmail constructs an HTML-formatted email for user feedback
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Validate required fields
	if strings.TrimSpace(fromAddr) == "" {
		return "", errors.New("from address is required")
	}
	if strings.TrimSpace(toAddr) == "" {
		return "", errors.New("to address is required")
	}
	if strings.TrimSpace(userName) == "" {
		return "", errors.New("username is required")
	}
	if strings.TrimSpace(subject) == "" {
		return "", errors.New("subject is required")
	}
	if strings.TrimSpace(feedbackContent) == "" {
		return "", errors.New("feedback content is required")
	}

	// Validate email addresses
	if _, err := mail.ParseAddress(fromAddr); err != nil {
		return "", fmt.Errorf("invalid from address: %v", err)
	}
	if _, err := mail.ParseAddress(toAddr); err != nil {
		return "", fmt.Errorf("invalid to address: %v", err)
	}

	// Escape HTML special characters to prevent XSS
	escapedUserName := html.EscapeString(userName)
	escapedSubject := html.EscapeString(subject)
	escapedFeedbackContent := html.EscapeString(feedbackContent)

