// sanitizeHeaderValue removes characters that could be used for email header injection
// This prevents CRLF injection attacks in email headers
func sanitizeHeaderValue(value string) string {
	// Remove carriage return and line feed characters
	value = strings.ReplaceAll(value, "\r", "")
	value = strings.ReplaceAll(value, "\n", "")
	// Also remove null bytes
	value = strings.ReplaceAll(value, "\x00", "")
	return value
}

