		"support@example.com",
		"John <script>alert('xss')</script> Doe",
		"Test Subject\r\nBcc: attacker@evil.com",
		"This is my feedback with <b>HTML</b> tags",
	)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Println(email)
}

