// sanitizeHeaderValue removes characters that could be used for email header injection
// This includes CR (\r), LF (\n), and null bytes
func sanitizeHeaderValue(input string) string {
	// Remove carriage return, line feed, and null bytes
	result := strings.ReplaceAll(input, "\r", "")
	result = strings.ReplaceAll(result, "\n", "")
	result = strings.ReplaceAll(result, "\x00", "")
	return result
}

